def cautare_binara(lista, x):
    stanga, dreapta = 0, len(lista) - 1
    while stanga <= dreapta:
        mijloc = (stanga + dreapta) // 2
        if lista[mijloc] == x:
            return mijloc
        elif lista[mijloc] < x:
            stanga = mijloc + 1
        else:
            dreapta = mijloc - 1
    return -1

