def cezar(text, deplasare):
    rez = ""
    for c in text:
        if c.isalpha():
            baza = ord('a')
            rez += chr((ord(c) - baza + deplasare) % 26 + baza)
        else:
            rez += c
    return rez

print(cezar("abc", 2))

