def vigenere(text, cheie):
    rez = ""
    i = 0
    for c in text:
        if c.isalpha():
            baza = ord('a')
            depl = ord(cheie[i % len(cheie)]) - ord('a')
            rez += chr((ord(c) - baza + depl) % 26 + baza)
            i += 1
        else:
            rez += c
    return rez

print(vigenere("aaaa", "ab"))

