def quicksort(lista):
    if len(lista) <= 1:
        return lista
    pivot = lista[0]
    stanga = [x for x in lista[1:] if x < pivot]
    dreapta = [x for x in lista[1:] if x >= pivot]
    return quicksort(stanga) + [pivot] + quicksort(dreapta)

print(quicksort([3, 1, 2]))

