def rest_greedy(suma, monede):
    monede = sorted(monede, reverse=True)
    rez = []
    for m in monede:
        while suma >= m:
            rez.append(m)
            suma -= m
    return rez if suma == 0 else None

print(rest_greedy(7, [1, 3, 4]))

